import{_ as l,a0 as p,w as o,s as u,ao as h,I as t,x as a,a1 as i,A as e}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const m=JSON.parse('{"title":"查找 Linux 发行版名称、版本和内核详细信息 | LCTT x X-CMD","titleTemplate":false,"description":"查找 Linux 发行版名称、版本和内核详细信息 | LCTT (201908) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"查找 Linux 发行版名称、版本和内核详细信息 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"查找 Linux 发行版名称、版本和内核详细信息 | LCTT (201908) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201908/20190805 Find The Linux Distribution Name, Version And Kernel Details","title":"查找 Linux 发行版名称、版本和内核详细信息","tag":"201908","desc":""},"relativePath":"201908/20190805 Find The Linux Distribution Name, Version And Kernel Details.md","filePath":"[post].md"}'),r={name:"201908/20190805 Find The Linux Distribution Name, Version And Kernel Details.md"};function d(c,s,g,b,k,x){const n=p("Link");return o(),u("div",null,[s[15]||(s[15]=h(`<h1 id="查找-linux-发行版名称、版本和内核详细信息" tabindex="-1">查找 Linux 发行版名称、版本和内核详细信息 <a class="header-anchor" href="#查找-linux-发行版名称、版本和内核详细信息" aria-label="Permalink to “查找 Linux 发行版名称、版本和内核详细信息”">​</a></h1><p><img src="https://www.ostechnix.com/wp-content/uploads/2015/08/Linux-Distribution-Name-Version-Kernel-720x340.png" alt="Find The Linux Distribution Name, Version And Kernel Details"></p><p>本指南介绍了如何查找 Linux 发行版名称、版本和内核详细信息。如果你的 Linux 系统有 GUI 界面，那么你可以从系统设置中轻松找到这些信息。但在命令行模式下，初学者很难找到这些详情。没有问题！我这里给出了一些命令行方法来查找 Linux 系统信息。可能有很多，但这些方法适用于大多数 Linux 发行版。</p><h3 id="_1、查找-linux-发行版名称、版本" tabindex="-1">1、查找 Linux 发行版名称、版本 <a class="header-anchor" href="#_1、查找-linux-发行版名称、版本" aria-label="Permalink to “1、查找 Linux 发行版名称、版本”">​</a></h3><p>有很多方法可以找出 VPS 中运行的操作系统。</p><h4 id="方法-1" tabindex="-1">方法 1： <a class="header-anchor" href="#方法-1" aria-label="Permalink to “方法 1：”">​</a></h4><p>打开终端并运行以下命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ cat /etc/*-release</span></span></code></pre></div><p>CentOS 7 上的示例输出：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>CentOS Linux release 7.0.1406 (Core)</span></span>
<span class="line"><span>NAME=&quot;CentOS Linux&quot;</span></span>
<span class="line"><span>VERSION=&quot;7 (Core)&quot;</span></span>
<span class="line"><span>ID=&quot;centos&quot;</span></span>
<span class="line"><span>ID_LIKE=&quot;rhel fedora&quot;</span></span>
<span class="line"><span>VERSION_ID=&quot;7&quot;</span></span>
<span class="line"><span>PRETTY_NAME=&quot;CentOS Linux 7 (Core)&quot;</span></span>
<span class="line"><span>ANSI_COLOR=&quot;0;31&quot;</span></span>
<span class="line"><span>CPE_NAME=&quot;cpe:/o:centos:centos:7&quot;</span></span>
<span class="line"><span>HOME_URL=&quot;https://www.centos.org/&quot;</span></span>
<span class="line"><span>BUG_REPORT_URL=&quot;https://bugs.centos.org/&quot;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>CentOS Linux release 7.0.1406 (Core)</span></span>
<span class="line"><span>CentOS Linux release 7.0.1406 (Core)</span></span></code></pre></div><p>Ubuntu 18.04 上的示例输出：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>DISTRIB_ID=Ubuntu</span></span>
<span class="line"><span>DISTRIB_RELEASE=18.04</span></span>
<span class="line"><span>DISTRIB_CODENAME=bionic</span></span>
<span class="line"><span>DISTRIB_DESCRIPTION=&quot;Ubuntu 18.04.2 LTS&quot;</span></span>
<span class="line"><span>NAME=&quot;Ubuntu&quot;</span></span>
<span class="line"><span>VERSION=&quot;18.04.2 LTS (Bionic Beaver)&quot;</span></span>
<span class="line"><span>ID=ubuntu</span></span>
<span class="line"><span>ID_LIKE=debian</span></span>
<span class="line"><span>PRETTY_NAME=&quot;Ubuntu 18.04.2 LTS&quot;</span></span>
<span class="line"><span>VERSION_ID=&quot;18.04&quot;</span></span>
<span class="line"><span>HOME_URL=&quot;https://www.ubuntu.com/&quot;</span></span>
<span class="line"><span>SUPPORT_URL=&quot;https://help.ubuntu.com/&quot;</span></span>
<span class="line"><span>BUG_REPORT_URL=&quot;https://bugs.launchpad.net/ubuntu/&quot;</span></span>
<span class="line"><span>PRIVACY_POLICY_URL=&quot;https://www.ubuntu.com/legal/terms-and-policies/privacy-policy&quot;</span></span>
<span class="line"><span>VERSION_CODENAME=bionic</span></span>
<span class="line"><span>UBUNTU_CODENAME=bionic</span></span></code></pre></div><h4 id="方法-2" tabindex="-1">方法 2： <a class="header-anchor" href="#方法-2" aria-label="Permalink to “方法 2：”">​</a></h4><p>以下命令也能获取你发行版的详细信息。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ cat /etc/issue</span></span></code></pre></div><p>Ubuntu 18.04 上的示例输出：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Ubuntu 18.04.2 LTS \\n \\l</span></span></code></pre></div><h4 id="方法-3" tabindex="-1">方法 3： <a class="header-anchor" href="#方法-3" aria-label="Permalink to “方法 3：”">​</a></h4><p>以下命令能在 Debian 及其衍生版如 Ubuntu、Linux Mint 上获取发行版详细信息。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ lsb_release -a</span></span></code></pre></div><p>示例输出：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>No LSB modules are available.</span></span>
<span class="line"><span>Distributor ID: Ubuntu</span></span>
<span class="line"><span>Description:    Ubuntu 18.04.2 LTS</span></span>
<span class="line"><span>Release:    18.04</span></span>
<span class="line"><span>Codename:   bionic</span></span></code></pre></div><h3 id="_2、查找-linux-内核详细信息" tabindex="-1">2、查找 Linux 内核详细信息 <a class="header-anchor" href="#_2、查找-linux-内核详细信息" aria-label="Permalink to “2、查找 Linux 内核详细信息”">​</a></h3><h4 id="方法-1-1" tabindex="-1">方法 1： <a class="header-anchor" href="#方法-1-1" aria-label="Permalink to “方法 1：”">​</a></h4><p>要查找 Linux 内核详细信息，请在终端运行以下命令。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ uname -a</span></span></code></pre></div><p>CentOS 7 上的示例输出：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Linux server.ostechnix.lan 3.10.0-123.9.3.el7.x86_64 #1 SMP Thu Nov 6 15:06:03 UTC 2014 x86_64 x86_64 x86_64 GNU/Linux</span></span></code></pre></div><p>Ubuntu 18.04 上的示例输出：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Linux ostechnix 4.18.0-25-generic #26~18.04.1-Ubuntu SMP Thu Jun 27 07:28:31 UTC 2019 x86_64 x86_64 x86_64 GNU/Linux</span></span></code></pre></div><p>或者，</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ uname -mrs</span></span></code></pre></div><p>示例输出：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Linux 4.18.0-25-generic x86_64</span></span></code></pre></div><p>这里，</p><ul><li><code>Linux</code> – 内核名</li><li><code>4.18.0-25-generic</code> – 内核版本</li><li><code>x86_64</code> – 系统硬件架构（即 64 位系统）</li></ul><p>有关 <code>uname</code> 命令的更多详细信息，请参考手册页。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ man uname</span></span></code></pre></div><h4 id="方法2" tabindex="-1">方法2： <a class="header-anchor" href="#方法2" aria-label="Permalink to “方法2：”">​</a></h4><p>在终端中，运行以下命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ cat /proc/version</span></span></code></pre></div><p>CentOS 7 上的示例输出：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Linux version 3.10.0-123.9.3.el7.x86_64 ([email protected]) (gcc version 4.8.2 20140120 (Red Hat 4.8.2-16) (GCC) ) #1 SMP Thu Nov 6 15:06:03 UTC 2014</span></span></code></pre></div><p>Ubuntu 18.04 上的示例输出：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Linux version 4.18.0-25-generic ([email protected]) (gcc version 7.4.0 (Ubuntu 7.4.0-1ubuntu1~18.04.1)) #26~18.04.1-Ubuntu SMP Thu Jun 27 07:28:31 UTC 2019</span></span></code></pre></div><p>这些是查找 Linux 发行版的名称、版本和内核详细信息的几种方法。希望你觉得它有用。</p><hr>`,47)),t("p",null,[s[1]||(s[1]=a("via: ",-1)),i(n,{href:"https://www.ostechnix.com/find-out-the-linux-distribution-name-version-and-kernel-details/"},{default:e(()=>[...s[0]||(s[0]=[a("https://www.ostechnix.com/find-out-the-linux-distribution-name-version-and-kernel-details/",-1)])]),_:1})]),t("p",null,[s[6]||(s[6]=a("作者：",-1)),i(n,{href:"https://www.ostechnix.com/author/sk/"},{default:e(()=>[...s[2]||(s[2]=[a("sk",-1)])]),_:1}),s[7]||(s[7]=a(" 选题：",-1)),i(n,{href:"https://github.com/lujun9972"},{default:e(()=>[...s[3]||(s[3]=[a("lujun9972",-1)])]),_:1}),s[8]||(s[8]=a(" 译者：",-1)),i(n,{href:"https://github.com/geekpi"},{default:e(()=>[...s[4]||(s[4]=[a("geekpi",-1)])]),_:1}),s[9]||(s[9]=a(" 校对：",-1)),i(n,{href:"https://github.com/wxy"},{default:e(()=>[...s[5]||(s[5]=[a("wxy",-1)])]),_:1})]),t("p",null,[s[12]||(s[12]=a("本文由 ",-1)),i(n,{href:"https://github.com/LCTT/TranslateProject"},{default:e(()=>[...s[10]||(s[10]=[a("LCTT",-1)])]),_:1}),s[13]||(s[13]=a(" 原创编译，",-1)),i(n,{href:"https://linux.cn/"},{default:e(()=>[...s[11]||(s[11]=[a("Linux中国",-1)])]),_:1}),s[14]||(s[14]=a(" 荣誉推出",-1))])])}const L=l(r,[["render",d]]);export{m as __pageData,L as default};
